types.text:
interface MuxUICollectionItem {
  id?: string;
  key?: string;
  label?: React.ReactNode;
  value?: string;
  textValue?: string;
  disabled?: boolean;
  [key: string]: unknown;
}

type MuxUIAriaAccessibleName = {
  'aria-label': string;
  'aria-labelledby'?: never;
} | {
  'aria-label'?: never;
  'aria-labelledby': string;
};

interface MuxUITreeItem extends MuxUICollectionItem {
  children?: MuxUITreeItem[];
  items?: MuxUITreeItem[];
}

type TreeOwnProps = {
  items?: MuxUITreeItem[];
  selectedIds?: MuxUISelection;
  defaultSelectedIds?: MuxUISelection;
  expandedIds?: MuxUISelection;
  defaultExpandedIds?: MuxUISelection;
  disabled?: boolean;
  selectionMode?: 'none' | 'single' | 'multiple';
  expansionTrigger?: 'chevron' | 'row';
  onSelectionChange?: (ids: MuxUISelection) => void;
  onExpandedChange?: (ids: MuxUISelection) => void;
  onAction?: (item?: MuxUITreeItem) => void;
};

type TreeProps = TreeOwnProps & {
  className?: string;
} & MuxUIAriaAccessibleName;
